$ErrorActionPreference = "Stop"

$ProjectRoot = (Get-Location).Path
$PackagePath = Join-Path $ProjectRoot "package.json"
$P03Path = Join-Path $ProjectRoot ".private\entity\build\P03\evidence-packets.json"
$CompilerPath = Join-Path $ProjectRoot "scripts\entity\build-cached-emet-explanations.js"
$BatchPath = Join-Path $ProjectRoot "scripts\entity\batch-cached-emet-explanations.js"
$SchedulerPath = Join-Path $ProjectRoot "scripts\entity\schedule-cached-emet-generation.js"
$PromptPath = Join-Path $ProjectRoot "scripts\entity\emet-prompts\emet-free-tier-v1.js"
$TestPath = Join-Path $ProjectRoot "scripts\entity\test-emet-reader-explanation.js"
$NotesPath = Join-Path $ProjectRoot "P04_CONTEXT_SAFE_READER_NOTES.md"
$SchedulerStatePath = Join-Path $ProjectRoot ".private\entity\build\P04\scheduler-state.json"
$GenerationStatePath = Join-Path $ProjectRoot ".private\entity\build\P04\generation-state.json"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot ".private\entity\backups\P04-context-safe-reader-v1.6.3-$Timestamp"

$CompilerPayload = ""

$BatchPayload = ""

$SchedulerPayload = ""

$PromptPayload = ""

$TestPayload = ""

$NotesPayload = ""

$InstalledPaths = @($CompilerPath, $BatchPath, $SchedulerPath, $PromptPath, $TestPath, $NotesPath)

function Write-Payload {
    param([Parameter(Mandatory)][string]$Payload, [Parameter(Mandatory)][string]$Path)
    $directory = Split-Path -Parent $Path
    New-Item -ItemType Directory -Force -Path $directory | Out-Null
    [System.IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($Payload))
}

function Backup-File {
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path $Path)) { return }
    $relative = $Path.Substring($ProjectRoot.Length).TrimStart('\', '/')
    $destination = Join-Path $BackupRoot $relative
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $destination) | Out-Null
    Copy-Item -Force $Path $destination
}

function Restore-Backup {
    foreach ($path in $InstalledPaths) {
        $relative = $path.Substring($ProjectRoot.Length).TrimStart('\', '/')
        $backup = Join-Path $BackupRoot $relative
        if (Test-Path $backup) {
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $path) | Out-Null
            Copy-Item -Force $backup $path
        } elseif (Test-Path $path) {
            Remove-Item -Force $path
        }
    }
    foreach ($path in @($PackagePath, $SchedulerStatePath, $GenerationStatePath)) {
        $relative = $path.Substring($ProjectRoot.Length).TrimStart('\', '/')
        $backup = Join-Path $BackupRoot $relative
        if (Test-Path $backup) {
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $path) | Out-Null
            Copy-Item -Force $backup $path
        }
    }
}

function Set-PackageScripts {
    $tempScript = Join-Path $ProjectRoot ".private\entity\update-p04-v162-package.js"
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $tempScript) | Out-Null
    $javascript = @'
const fs = require("fs");
const file = "package.json";
const raw = fs.readFileSync(file, "utf8").replace(/^\uFEFF/, "");
const pkg = JSON.parse(raw);
pkg.scripts = pkg.scripts || {};
Object.assign(pkg.scripts, {
  "build:cached-emet": "node --max-old-space-size=4096 scripts/entity/build-cached-emet-explanations.js",
  "verify:cached-emet": "node --max-old-space-size=4096 scripts/entity/build-cached-emet-explanations.js --verify",
  "prepare:cached-emet-batch": "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --prepare",
  "submit:cached-emet-batch": "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --submit",
  "status:cached-emet-batch": "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --status",
  "import:cached-emet-batch": "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --import",
  "verify:cached-emet-batch": "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --verify",
  "cancel:cached-emet-batch": "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --cancel",
  "emet:generate": "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --run",
  "emet:generate:plan": "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --plan",
  "emet:generate:status": "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --status",
  "emet:generate:watch": "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --run --watch",
  "emet:generate:reset": "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --reset",
  "test:emet-reader": "node --max-old-space-size=4096 scripts/entity/test-emet-reader-explanation.js"
});
fs.writeFileSync(file, JSON.stringify(pkg, null, 2) + "\n", "utf8");
'@
    [System.IO.File]::WriteAllText($tempScript, $javascript, (New-Object System.Text.UTF8Encoding($false)))
    & node $tempScript
    if ($LASTEXITCODE -ne 0) { throw "Unable to update package.json." }
    Remove-Item -Force $tempScript
}

function Clear-SupersededFailures {
    if (-not (Test-Path $GenerationStatePath)) { return }
    $state = Get-Content $GenerationStatePath -Raw -Encoding UTF8 | ConvertFrom-Json
    $previousFailureCount = 0
    if ($state.failures) { $previousFailureCount = @($state.failures.PSObject.Properties).Count }
    if ($state.PSObject.Properties.Name -contains "failures") {
        $state.failures = [pscustomobject]@{}
    } else {
        $state | Add-Member -NotePropertyName failures -NotePropertyValue ([pscustomobject]@{}) -Force
    }
    if ($state.PSObject.Properties.Name -contains "updatedAt") {
        $state.updatedAt = (Get-Date).ToUniversalTime().ToString("o")
    } else {
        $state | Add-Member -NotePropertyName updatedAt -NotePropertyValue ((Get-Date).ToUniversalTime().ToString("o")) -Force
    }
    $json = $state | ConvertTo-Json -Depth 100
    [System.IO.File]::WriteAllText((Resolve-Path $GenerationStatePath), $json + "`r`n", (New-Object System.Text.UTF8Encoding($false)))
    if ($previousFailureCount -gt 0) {
        Write-Host "Cleared $previousFailureCount failures from superseded prompt runs."
    }
}

function Supersede-OldSchedulerJob {
    if (-not (Test-Path $SchedulerStatePath)) { return }
    $state = Get-Content $SchedulerStatePath -Raw -Encoding UTF8 | ConvertFrom-Json
    $activeJobId = $state.activeJobId
    if (-not $state.history) { $state | Add-Member -NotePropertyName history -NotePropertyValue @() -Force }
    if ($activeJobId) {
        $historyItem = [pscustomobject]@{
            at = (Get-Date).ToUniversalTime().ToString("o")
            action = "superseded-reader-meaning-hotfix"
            jobId = $activeJobId
            newPromptVersion = "1.4.2"
        }
        $state.history = @($state.history) + $historyItem
        Write-Warning "Local Batch job $activeJobId belongs to the previous prompt and will not be imported by the new scheduler."
    }
    if ($state.PSObject.Properties.Name -contains "activeJobId") {
        $state.activeJobId = $null
    } else {
        $state | Add-Member -NotePropertyName activeJobId -NotePropertyValue $null -Force
    }
    if ($state.PSObject.Properties.Name -contains "nextEligibleSubmitAt") {
        $state.nextEligibleSubmitAt = $null
    } else {
        $state | Add-Member -NotePropertyName nextEligibleSubmitAt -NotePropertyValue $null -Force
    }
    if ($state.PSObject.Properties.Name -contains "updatedAt") {
        $state.updatedAt = (Get-Date).ToUniversalTime().ToString("o")
    } else {
        $state | Add-Member -NotePropertyName updatedAt -NotePropertyValue ((Get-Date).ToUniversalTime().ToString("o")) -Force
    }
    $json = $state | ConvertTo-Json -Depth 100
    [System.IO.File]::WriteAllText((Resolve-Path $SchedulerStatePath), $json + "`r`n", (New-Object System.Text.UTF8Encoding($false)))
}

function Assert-ReaderMeaningPolicy {
    $tempScript = Join-Path $ProjectRoot ".private\entity\assert-p04-v163-context-policy.js"
    $javascript = @'
const path = require("path");
const compiler = require(path.join(process.cwd(), "scripts", "entity", "build-cached-emet-explanations.js"));
const p03 = compiler.validateP03Artifact(
  compiler.readJson(
    path.join(process.cwd(), ".private", "entity", "build", "P03", "evidence-packets.json"),
    "P03 evidence packets"
  )
);
const prompt = compiler.promptDescriptor();
if (prompt.version !== "1.4.3") throw new Error(`Unexpected prompt version: ${prompt.version}`);

const h1077 = "word:hebrew:H1077";
const hPacket = p03.packets[h1077];
if (!hPacket) throw new Error(`Missing ${h1077} in P03.`);
const hBundle = compiler.buildGenerationBundle(hPacket, { enforceLimit: false });
const fallback = (hBundle.view.rendering_evidence.dominant_fallback_candidates || [])
  .map((item) => String(item.text || "").toLowerCase());
if (!fallback.includes("not") || fallback.includes("that")) {
  throw new Error(`H1077 fallback policy is invalid: ${fallback.join(", ")}`);
}

const g0119 = "word:greek-nt:G0119";
const gPacket = p03.packets[g0119];
if (!gPacket) throw new Error(`Missing ${g0119} in P03.`);
const gBundle = compiler.buildGenerationBundle(gPacket, { enforceLimit: false });
if (Object.prototype.hasOwnProperty.call(gBundle.view.identity || {}, "morphology_english")) {
  throw new Error("G0119 detailed morphology leaked into the reader generation view.");
}
if (gBundle.view.occurrence_evidence.verse_text_available !== false) {
  throw new Error("G0119 incorrectly reports verse text as available.");
}
if (gBundle.view.occurrence_evidence.surrounding_context_available !== false) {
  throw new Error("G0119 incorrectly reports surrounding context as available.");
}

const quality = gBundle.quality;
const good = "This Greek noun means contest or struggle. It describes a difficult effort or conflict in which someone must exert themselves rather than remain passive. In the Greek New Testament, it occurs once, in Hebrews 10:32. Because the word appears only once in this corpus, its general meaning is focused: it names the struggle or contest itself rather than the act of struggling. Its precise role in Hebrews 10:32 depends on the surrounding verse and passage, which belong in the separate contextual explanation shown when that verse is opened.";
const badReference = "This word means contest or struggle. In Hebrews 10:32, where its meaning is connected with a demanding experience requiring perseverance, it names a serious conflict.";
const badCorpus = "This word means contest or struggle. In Scripture, it appears once, in Hebrews 10:32.";
if (compiler.readerQualityFailure(good, g0119, quality)) {
  throw new Error("A valid context-safe G0119 explanation was rejected.");
}
if (compiler.readerQualityFailure(badReference, g0119, quality) !== "reference-context-inference") {
  throw new Error("Reference-led context inference was not rejected.");
}
if (compiler.readerQualityFailure(badCorpus, g0119, quality) !== "corpus-count-overreach") {
  throw new Error("Corpus-limited count overreach was not rejected.");
}

console.log(`Prompt contract          : ${prompt.id}@${prompt.version}`);
console.log(`H1077 approved fallback  : ${fallback.join(", ")}`);
console.log("G0119 morphology detail  : withheld");
console.log("G0119 verse text/context : unavailable");
console.log("Context inference gates  : passed");
'@
    [System.IO.File]::WriteAllText($tempScript, $javascript, (New-Object System.Text.UTF8Encoding($false)))
    & node $tempScript
    if ($LASTEXITCODE -ne 0) { throw "The context-safe reader policy assertion failed." }
    Remove-Item -Force $tempScript
}

if (-not (Test-Path $PackagePath)) { throw "Run this installer from the ai-bible-app project root. package.json was not found." }
if (-not (Test-Path $P03Path)) { throw "P03 evidence-packets.json was not found. Complete P03 first." }

New-Item -ItemType Directory -Force -Path $BackupRoot | Out-Null
foreach ($path in @($CompilerPath, $BatchPath, $SchedulerPath, $PromptPath, $TestPath, $NotesPath, $PackagePath, $SchedulerStatePath, $GenerationStatePath)) {
    Backup-File $path
}

try {
    Write-Host "Installing P04 context-safe reader hotfix v1.6.3..." -ForegroundColor Cyan
    Write-Payload $CompilerPayload $CompilerPath
    Write-Payload $BatchPayload $BatchPath
    Write-Payload $SchedulerPayload $SchedulerPath
    Write-Payload $PromptPayload $PromptPath
    Write-Payload $TestPayload $TestPath
    Write-Payload $NotesPayload $NotesPath
    Set-PackageScripts
    Supersede-OldSchedulerJob
    Clear-SupersededFailures

    foreach ($path in @($CompilerPath, $BatchPath, $SchedulerPath, $PromptPath, $TestPath)) {
        & node --check $path
        if ($LASTEXITCODE -ne 0) { throw "Syntax validation failed: $path" }
    }

    Write-Host "`nValidating the context-safe reader policy..." -ForegroundColor Cyan
    Assert-ReaderMeaningPolicy

    Write-Host "`nInspecting G0119 compact input..." -ForegroundColor Cyan
    & npm run build:cached-emet -- --inspect-input --entity word:greek-nt:G0119
    if ($LASTEXITCODE -ne 0) { throw "The G0119 compact-input inspection failed." }

    Write-Host "`nP04 context-safe reader hotfix v1.6.3 installed successfully." -ForegroundColor Green
    Write-Host "Backup: $BackupRoot"
    Write-Host "`nNext command:"
    Write-Host "npm run test:emet-reader -- --entity word:greek-nt:G0119" -ForegroundColor Yellow
    Write-Host "`nDo not restart emet:generate:watch until the context-safe Greek NT review test is approved."
} catch {
    Write-Warning "Installation failed. Restoring the previous files..."
    Restore-Backup
    throw
}
